app = Flask(__name__)

# Whitelist of trusted domains
TRUSTED_DOMAINS = ['example.com', 'yourtrusteddomain.com']

def is_valid_url(url):
    # Check if URL matches the pattern and belongs to trusted domains
    regex = r'^https?://[^\s/$.?#].[^\s]*$'
    if re.match(regex, url):
        domain = url.split('/')[2]  # Extract domain from URL
        return any(domain.endswith(trusted_domain) for trusted_domain in TRUSTED_DOMAINS)
    return False

@app.route('/redirect')
def redirectToTarget():
    target_url = request.args.get('url')

    if target_url and is_valid_url(target_url):
        return redirect(target_url)

    # Log invalid attempts for security monitoring
    app.logger.warning(f'Invalid redirect attempt: {target_url}')
    return jsonify({"error": "Invalid URL"}), 400

