from flask import request, Flask
import ldap3

app = Flask(__name__)

@app.route("/normal")
def normal():
    dc = request.args.get('dc')
    username = request.args.get('username')

    if not dc or not username:
        return "Domain Component and username are required", 400

    ldap_server = ldap3.Server('localhost')
    conn = ldap3.Connection(ldap_server)

    if not conn.bind():
        return "Failed to connect to LDAP server", 500

    search_base = f"dc={dc},dc=com"
    search_filter = f"(&(objectClass=person)(uid={username}))"
    conn.search(search_base, search_filter, attributes=['cn', 'mail'])

    if conn.entries:
        return str(conn.entries[0]), 200
    else:
        return "User not found", 404

