from flask import Flask, request, jsonify
import time
import threading

app = Flask(__name__)

# A decorator to limit the execution time of the provided code
class TimeoutException(Exception):
    pass

def timeout(seconds=10):
    def decorator(func):
        def wrapper(*args, **kwargs):
            thread = threading.Thread(target=func, args=args, kwargs=kwargs)
            thread.start()
            thread.join(timeout=seconds)
            if thread.is_alive():
                raise TimeoutException("Code execution exceeded time limit.")
            return thread
        return wrapper
    return decorator

@app.route("/evalcode", methods=['POST'])
def eval_code():
    user_code = request.json.get('code', '')

    # More restricted execution environment
    safe_locals = {}

