from django.http import HttpResponse
import re

def xpath_query(request):
    xpath_value = request.GET.get('xpath')
    xml_value = request.GET.get('xml')

    # Input validation
    if not re.match(r'^[\w-]+$', xpath_value):  # Assuming valid IDs are alphanumeric and underscores
        return HttpResponse('Invalid XPath value.', status=400)

    # Limit XML size
    if len(xml_value) > 1024 * 1024:  # Limit to 1MB
        return HttpResponse('XML too large.', status=400)

    # Disable external entity processing to prevent XXE
    parser = etree.XMLParser(remove_blank_text=True, load_dtd=False, resolve_entities=False)

    try:
        xml_tree = etree.parse(StringIO(xml_value), parser)
    except etree.XMLSyntaxError:
        return HttpResponse('Malformed XML.', status=400)

    # Safe XPath query
    result = xml_tree.xpath(f"/tag[@id='{xpath_value}']")

    # Improved error handling
    if not result:
        return HttpResponse('No results found.', status=404)

    response_content = etree.tostring(result[0], pretty_print=True).decode('utf-8')

    return HttpResponse(response_content, content_type='application/xml')

