LOGIN_ATTEMPTS = {}
RATE_LIMIT_WINDOW = 60  # seconds
MAX_ATTEMPTS = 5
TABLE_NAME = 'users'

logging.basicConfig(level=logging.INFO)

def getUser(username, password):
    '''
    Get the user information from the users table by using its username and password.
    '''
    current_time = time()

    # Rate limiting
    if username in LOGIN_ATTEMPTS:
        attempts, first_attempt_time = LOGIN_ATTEMPTS[username]
        if current_time - first_attempt_time < RATE_LIMIT_WINDOW:
            if attempts >= MAX_ATTEMPTS:
                logging.warning("Too many login attempts for user: {}".format(username))
                return None
        else:
            LOGIN_ATTEMPTS[username] = [0, current_time]

    try:
        response = DYNAMO_CLIENT.get_item(
            TableName=TABLE_NAME,
            Key={'username': {'S': username}}
        )
        user = response.get('Item')
        if user and 'password' in user:
            if check_password_hash(user['password']['S'], password):
                return user
            else:
                LOGIN_ATTEMPTS[username][0] = LOGIN_ATTEMPTS[username][0] + 1
                logging.warning("Invalid password attempt for user: {}".format(username))
                return None
        else:
            return None
    except ClientError as e:
        logging.error("Error fetching user: {}".format(str(e)))
        return None
    except Exception as e:
        logging.error("Unexpected error: {}".format(str(e)))
        return None

def createUser(username, password):
    '''
    Create a new user with a hashed password.
    '''
    hashed_password = generate_password_hash(password)
    try:
        DYNAMO_CLIENT.put_item(
            TableName=TABLE_NAME,
            Item={
                'username': {'S': username},
                'password': {'S': hashed_password}
            }
        )
    except ClientError as e:
        logging.error("Error creating user: {}".format(str(e)))
        return False
    return True

